server.registerTool(
  "list_tasks",
  { description: "List the user's open tasks. Read-only.", inputSchema: { q: z.string() }, annotations: { readOnlyHint: true } },
  async ({ q }) => {
    const tasks = await db.tasks.findMany({ where: { open: true } });
